effect.shader:
const int MAXIMO_DE_CAMADAS = 5;

float hash2(vec2 c) {
    c += vec2(float(seed) * 13.7);
    return fract(sin(dot(c, vec2(127.1, 311.7))) * 43758.5453);
}

/**
 * O brilho do floco numa camada: 1 passe pelo grid dessa camada.
 * Cada célula tem UM floco, cujo lugar na célula é fixo (hash) e cujo Y
 * cai com o tempo, voltando ao topo ao sair.
 */
float neveDaCamada(vec2 uv, float t, float densidadeDaCamada, float velocidadeDaCamada, float tamanhoDaCamada) {
    vec2 grade = vec2(densidadeDaCamada, densidadeDaCamada);
    vec2 escalado = uv * grade;
    vec2 i = floor(escalado);
    vec2 f = fract(escalado);

    float xDoFloco = hash2(i + 0.1);
    float yFase = hash2(i + 0.3);
    float tamDoFloco = mix(0.25, 1.0, hash2(i + 0.7));

    // Y cai no tempo, começa em uma fase diferente para cada célula; vento desloca x.
    float y = fract(yFase + t * velocidadeDaCamada);
    float x = fract(xDoFloco + t * wind);

    vec2 pontoDoFloco = vec2(x, 1.0 - y);
    vec2 dentroDaCelula = (f - pontoDoFloco);
    float d = length(dentroDaCelula);

    float raio = tamanhoDaCamada * tamDoFloco * 0.3;
    float floco = 1.0 - smoothstep(0.0, raio, d);
    return floco;
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    int n = clamp(int(layers + 0.5), 1, MAXIMO_DE_CAMADAS);
    float acumulado = 0.0;

    for (int k = 0; k < MAXIMO_DE_CAMADAS; k++) {
        if (k >= n) break;
        float profundidade = (float(k) + 1.0) / float(n);           // 1/n a 1: 1 = frente
        float dens = density * (0.5 + 0.5 * profundidade);
        float vel = speed * (0.6 + profundidade);
        float tam = size * profundidade;
        acumulado = max(acumulado, neveDaCamada(acScreenNorm, acTime, dens, vel, tam) * profundidade);
    }

    float alfaFloco = clamp(acumulado, 0.0, 1.0) * flakeColor.a;

    vec3 cor = mix(original.rgb, flakeColor.rgb, alfaFloco);
    float alfa = max(original.a, alfaFloco);

    fragColor = vec4(cor, alfa);
}
